# feature: F06
"""Algorithm identities and frozen independent X.690 reference vectors.

Identifiers were checked against the original public algorithm descriptions;
no expected member is discovered from a product registry at run time.
"""


# The acceptance image does not include pyasn1. These frozen encodings were
# generated by pyasn1 0.4.8 outside the product, rather than by a product codec.
# Missing vectors are errors; no runtime encoder or fallback is used.
import json
from _helpers import support_path


def _algorithm_reference_vector(key):
    data = json.loads(support_path('F06_vectors.json').read_text())
    return bytes.fromhex(data['vectors'][json.dumps(key, separators=(',', ':'))])


def algo_der_sequence(*children):
    return _algorithm_reference_vector(['sequence', [v.hex() for v in children]])


def algo_der_integer(value):
    return _algorithm_reference_vector(['integer', value])


def algo_der_octets(value):
    return _algorithm_reference_vector(['octets', value.hex()])


def algo_der_identifier(oid, parameters=None):
    return _algorithm_reference_vector(['identifier', oid, None if parameters is None else parameters.hex()])


def algo_der_explicit(number, encoded):
    return _algorithm_reference_vector(['explicit', number, encoded.hex()])


