def signature_identities():
    """Yield identity, OID, signature family and digest, independently listed."""
    for digest, suffix in (('md2', 2), ('md5', 4), ('sha1', 5),
                           ('sha224', 14), ('sha256', 11),
                           ('sha384', 12), ('sha512', 13)):
        yield digest + '_rsa', '1.2.840.113549.1.1.%d' % suffix, 'rsassa_pkcs1v15', digest
    yield 'sha1_dsa', '1.2.840.10040.4.3', 'dsa', 'sha1'
    yield 'sha1_ecdsa', '1.2.840.10045.4.1', 'ecdsa', 'sha1'
    for index, digest in enumerate(('sha224', 'sha256', 'sha384', 'sha512'), 1):
        yield digest + '_dsa', '2.16.840.1.101.3.4.3.%d' % index, 'dsa', digest
        yield digest + '_ecdsa', '1.2.840.10045.4.3.%d' % index, 'ecdsa', digest
    for family, offset in (('dsa', 4), ('ecdsa', 8), ('rsa', 12)):
        for index, bits in enumerate((224, 256, 384, 512), 1):
            digest = 'sha3_%d' % bits
            yield (digest + '_' + family, '2.16.840.1.101.3.4.3.%d' % (offset + index),
                   'rsassa_pkcs1v15' if family == 'rsa' else family, digest)
    for suffix, digest in ((1, 'sha1'), (2, 'sha224'), (3, 'sha256'),
                           (4, 'sha384'), (5, 'sha512'), (8, 'sha3_224'),
                           (9, 'sha3_256'), (10, 'sha3_384'), (11, 'sha3_512')):
        yield digest + '_ecdsa_plain', '0.4.0.127.0.7.1.1.4.1.%d' % suffix, 'ecdsa', digest


