def checked_algorithm_descriptions(case, cls, name, oid, parameters, encoded_parameters):
    """Exercise creation and independent-input loading, then return both values."""
    wire = algo_der_identifier(oid, encoded_parameters)
    fields = {'algorithm': name}
    if parameters is not None:
        fields['parameters'] = parameters
    values = (cls(fields), cls.load(wire))
    for value in values:
        case.assertEqual(value['algorithm'].native, name)
        case.assertEqual(value['algorithm'].dotted, oid)
        case.assertEqual(value.dump(), wire)
        if encoded_parameters is not None:
            case.assertEqual(value['parameters'].dump(), encoded_parameters)
    return values


def pbkdf2_description(salt, iterations, key_length=None, prf=None):
    """Return caller fields and independent PKCS#5 DER, including defaults."""
    fields = {'salt': ('specified', salt), 'iteration_count': iterations}
    parts = [algo_der_octets(salt), algo_der_integer(iterations)]
    if key_length is not None:
        fields['key_length'] = key_length
        parts.append(algo_der_integer(key_length))
    if prf is not None:
        name, oid = prf
        fields['prf'] = {'algorithm': name}
        parts.append(algo_der_identifier(oid))
    return fields, algo_der_sequence(*parts)
